create table public.ep_countries (
  id integer generated by default as identity (start with 1003) primary key,
  name varchar(200) not null,
  cname varchar(200) not null,
  abbr varchar(20) not null,
  region integer not null,
  is_real boolean not null,
  is_distinguish_entry boolean not null,
  epv_supported boolean not null,
  epv_single_supported boolean not null,
  epv_trans_requirement integer not null,
  official_currency integer not null,
  enabled boolean not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.ep_countries is
  'EP country dictionary imported from the legacy patent platform.';

create table public.patent_language_options (
  id integer generated by default as identity (start with 1001) primary key,
  language_id integer not null,
  country_id integer not null,
  short_name varchar(50) not null,
  deleted boolean not null,
  zh_name varchar(100),
  en_name varchar(100),
  online_support_s_lang boolean,
  online_support_t_lang boolean,
  is_common_s_lang boolean,
  is_common_t_lang boolean,
  short_name_trans_doc varchar(50) not null,
  mt_discount_factor numeric(10, 4) not null,
  slang_sort_no integer not null,
  tlang_sort_no integer not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (short_name)
);

comment on table public.patent_language_options is
  'Patent language-country options imported from the legacy patent platform.';

alter table public.translation_requirements
  add column ep_country_ids integer[] not null default '{}'::integer[],
  add constraint translation_requirements_ep_country_ids_no_nulls
    check (array_position(ep_country_ids, null) is null);

alter table public.task_deliverables
  add column ep_country_id integer references public.ep_countries(id)
    on update restrict on delete restrict,
  add constraint task_deliverables_single_country_identity
    check (ep_country_id is null or jurisdiction_code is null);

create index ep_countries_enabled_name_idx
  on public.ep_countries(enabled, name);
create index patent_language_options_source_sort_idx
  on public.patent_language_options(deleted, slang_sort_no);
create index patent_language_options_target_sort_idx
  on public.patent_language_options(deleted, tlang_sort_no);
create unique index task_deliverables_task_ep_country_version_idx
  on public.task_deliverables(task_id, ep_country_id, version_no)
  where ep_country_id is not null;
create unique index task_deliverables_one_draft_per_ep_country_idx
  on public.task_deliverables(task_id, ep_country_id)
  where status = 'draft' and ep_country_id is not null;
create index task_deliverables_ep_country_status_version_idx
  on public.task_deliverables(task_id, ep_country_id, status, version_no desc)
  where ep_country_id is not null;

create trigger set_ep_countries_updated_at
before update on public.ep_countries
for each row execute function public.set_updated_at();

create trigger set_patent_language_options_updated_at
before update on public.patent_language_options
for each row execute function public.set_updated_at();

