do $$
begin
  if (select count(*) from public.ep_countries) <> 49 then
    raise exception 'Expected 49 EP country rows after import.';
  end if;
  if (select count(*) from public.patent_language_options) <> 330 then
    raise exception 'Expected 330 patent language rows after import.';
  end if;
end;
$$;

alter table public.ep_countries enable row level security;
alter table public.patent_language_options enable row level security;

revoke all on table public.ep_countries from anon, authenticated;
revoke all on table public.patent_language_options from anon, authenticated;
grant select on table public.ep_countries to authenticated;
grant select on table public.patent_language_options to authenticated;
grant select, insert, update, delete on table public.ep_countries to service_role;
grant select, insert, update, delete on table public.patent_language_options to service_role;
grant usage, select on sequence public.ep_countries_id_seq to service_role;
grant usage, select on sequence public.patent_language_options_id_seq to service_role;

create policy "Authenticated users can read enabled EP countries"
on public.ep_countries for select
to authenticated
using (enabled);

create policy "Authenticated users can read active patent languages"
on public.patent_language_options for select
to authenticated
using (not deleted);
